* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #f2efdf; background: #182321; }
body { min-height: 100vh; margin: 0; padding: 24px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #31463d 0%, #202e29 45%, #182321 100%); }
.board { width: min(100%, 560px); padding: clamp(24px, 6vw, 44px); border: 1px solid #536454; border-radius: 20px; background: #293731; box-shadow: 0 24px 70px #0c1512aa, inset 0 1px #ffffff12; text-align: center; }
.header { margin-bottom: 28px; }
.eyebrow, .footer { margin: 0; color: #b4bf9a; font-size: 16px; font-weight: 700; letter-spacing: .12em; }
h1 { margin: 10px 0 8px; font-size: clamp(28px, 7vw, 40px); line-height: 1.1; letter-spacing: -.04em; }
.hint { margin: 0; color: #c6c9b9; font-size: 16px; line-height: 1.5; }
.clocks { display: grid; gap: 14px; }
.clock { min-height: 150px; width: 100%; padding: 18px 22px; display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto 1fr; align-items: center; text-align: left; color: #f2efdf; background: #202b27; border: 2px solid #45554a; border-radius: 12px; cursor: pointer; transition: border-color .15s, background .15s, transform .15s, box-shadow .15s; }
.clock:hover:not(:disabled) { border-color: #b4bf9a; background: #26332d; }
.clock:active:not(:disabled) { transform: scale(.985); }
.clock:focus-visible, .pause:focus-visible { outline: 3px solid #e2c46e; outline-offset: 4px; }
.clock.active { border-color: #e2c46e; box-shadow: 0 0 0 1px #e2c46e33, 0 0 26px #e2c46e17; }
.clock:disabled { cursor: default; }
.player { display: flex; gap: 10px; align-items: center; font-size: 18px; font-weight: 700; }
.piece { width: 14px; height: 14px; display: inline-block; border: 2px solid #e2c46e; border-radius: 2px; transform: rotate(45deg); }
.white-piece { background: #f2efdf; border-color: #b4bf9a; }
.black-piece { background: #182321; }
.time { grid-column: 2; grid-row: 1 / 3; font-variant-numeric: tabular-nums; font-size: clamp(48px, 12vw, 68px); font-weight: 750; line-height: 1; letter-spacing: -.06em; }
.clock-label { margin-top: 8px; color: #b4bf9a; font-size: 16px; font-weight: 800; letter-spacing: .12em; }
.clock.active .clock-label { color: #e2c46e; }
.status { min-height: 28px; margin: 22px 0 14px; color: #e2c46e; font-size: 18px; font-weight: 700; }
.pause { min-width: 148px; min-height: 52px; padding: 10px 20px; color: #182321; background: #e2c46e; border: 0; border-radius: 8px; font: inherit; font-size: 18px; font-weight: 750; cursor: pointer; transition: background .15s, transform .15s; }
.pause:hover:not(:disabled) { background: #f0d783; }
.pause:active:not(:disabled) { transform: translateY(2px); }
.pause:disabled { opacity: .45; cursor: not-allowed; }
.pause span { margin-left: 6px; }
.footer { margin-top: 28px; font-size: 13px; letter-spacing: .1em; }
@media (max-width: 420px) { body { padding: 16px; } .board { padding: 24px 18px; } .clock { min-height: 132px; padding: 16px; } .player { font-size: 16px; } }

(() => {
  const START_MS = 5 * 60 * 1000;
  const remaining = { white: START_MS, black: START_MS };
  const buttons = { white: document.getElementById('white-clock'), black: document.getElementById('black-clock') };
  const times = { white: document.getElementById('white-time'), black: document.getElementById('black-time') };
  const labels = { white: document.getElementById('white-label'), black: document.getElementById('black-label') };
  const status = document.getElementById('status');
  const pauseButton = document.getElementById('pause');
  let active = null;
  let deadline = 0;
  let paused = false;
  let flagged = false;
  let ticker = null;

  const format = ms => {
    const seconds = Math.ceil(ms / 1000);
    return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
  };

  function render() {
    for (const side of ['white', 'black']) {
      times[side].textContent = format(remaining[side]);
      const isActive = side === active && !paused && !flagged;
      buttons[side].classList.toggle('active', isActive || (!active && !flagged && side === 'white'));
      buttons[side].setAttribute('aria-pressed', String(isActive));
      buttons[side].setAttribute('aria-label', `${side[0].toUpperCase() + side.slice(1)} clock, ${format(remaining[side])} remaining. ${flagged ? 'Game over.' : paused ? 'Clock paused.' : isActive ? 'Your turn. Tap to switch.' : 'Tap to start or switch turns.'}`);
      labels[side].textContent = flagged && remaining[side] === 0 ? 'FLAGGED' : isActive ? 'YOUR TURN' : paused && side === active ? 'PAUSED' : 'READY';
    }
    pauseButton.disabled = active === null || flagged;
    pauseButton.innerHTML = paused ? '▶ <span>Resume</span>' : 'Ⅱ <span>Pause</span>';
    pauseButton.setAttribute('aria-label', paused ? 'Resume clocks' : 'Pause clocks');
  }

  function update() {
    if (active === null || paused || flagged) return;
    remaining[active] = Math.max(0, deadline - Date.now());
    if (remaining[active] === 0) {
      flagged = true;
      clearInterval(ticker);
      ticker = null;
      status.textContent = `${active[0].toUpperCase() + active.slice(1)} Flag!`;
    }
    render();
  }

  function start(side) {
    if (flagged || paused) return;
    if (active === side) return;
    update();
    if (flagged) return;
    active = side;
    deadline = Date.now() + remaining[active];
    status.textContent = `${side[0].toUpperCase() + side.slice(1)} to move`;
    if (ticker === null) ticker = setInterval(update, 100);
    render();
  }

  for (const side of ['white', 'black']) buttons[side].addEventListener('click', () => start(side));

  pauseButton.addEventListener('click', () => {
    if (active === null || flagged) return;
    if (!paused) {
      const now = Date.now();
      remaining[active] = Math.max(0, deadline - now);
      if (remaining[active] === 0) {
        flagged = true;
        clearInterval(ticker);
        ticker = null;
        status.textContent = `${active[0].toUpperCase() + active.slice(1)} Flag!`;
        render();
        return;
      }
      paused = true;
      clearInterval(ticker);
      ticker = null;
      status.textContent = 'Clock paused';
    } else {
      paused = false;
      deadline = Date.now() + remaining[active];
      status.textContent = `${active[0].toUpperCase() + active.slice(1)} to move`;
      ticker = setInterval(update, 100);
    }
    render();
  });

  render();
})();
